// tetgen.cpp - Консольная сборка меш-генератора в C++Builder
#ifndef TETLIBRARY
int _tmain(int argc, _TCHAR *argv[])
{
    tetgenbehavior b;
    tetgenio in, addin, bgmin;

    if (!b.parse_commandline(argc, argv)) {
        terminatetetgen(NULL, 10);
    }

    // Считывание входных файлов узлов и граней
    if (b.refine) {
        in.load_node(b.infilename);
    } else {
        in.load_node(b.infilename);
    }

    // Вызов геометрического ядра триангуляции
    tetrahedralize(&b, &in, &out);

    // Сохранение результирующих сеток
    out.save_nodes(b.outfilename);
    out.save_elements(b.outfilename);
    out.save_faces(b.outfilename);
    out.save_edges(b.outfilename);
    out.save_neighbors(b.outfilename);

    return 0;
}
#endif

// Отрисовка рёбер триангуляции Делоне
void __fastcall TFormNetScene::DrawDelaunay()
{
    GLPoints1->Visible = true;
    GLLines1->Visible = true;
    GLLines1->Nodes->Clear();

    for (int i = 0; i < A_Delaunay.edgeCount; i++) {
        int n1 = A_Delaunay.edge[i][0];
        int n2 = A_Delaunay.edge[i][1];
        GLLines1->AddNode(A_Delaunay.node[n1][0] * 0.05,
                          A_Delaunay.node[n1][1] * 0.05,
                          A_Delaunay.node[n1][2] * 0.05);
        GLLines1->AddNode(A_Delaunay.node[n2][0] * 0.05,
                          A_Delaunay.node[n2][1] * 0.05,
                          A_Delaunay.node[n2][2] * 0.05);
    }
}

